import React, { useState, useEffect } from 'react'
import { View, Text, TouchableOpacity } from 'react-native'


import { styles } from './styles'
import Axios from 'axios';

export function Cards({ listItemProps, position }: any) {
    const cardNumber = String(listItemProps.data.lineCards + position)
    const randomText = Math.random().toString(36).substr(2, 5)

    const [, updateState] = React.useState();
    const forceUpdate = React.useCallback(() => updateState({}), []);

    function button() {
        Axios.post("http://18.191.178.251:3000/register", {
            number: Number(cardNumber),
            name: randomText,
            phone: '(00)000000000',
            price: 0
        }).then((response) => console.warn(response));
        forceUpdate()
    }


    function colorSelect() {
        if (listItemProps.db?.[cardNumber]) {
            if (listItemProps.db?.[cardNumber][0].price !== 0) {
                return { backgroundColor: '#26A744' }
            } else {
                return { backgroundColor: '#17A2B7' }
            }
        } else {
            return { backgroundColor: '#fff', color: '#121212' }
        }
    }

    return (
        <TouchableOpacity onPress={button}>
            <View>
                <Text style={[styles.listText, colorSelect()
                ]}>
                    {(`0000${cardNumber}`).slice(-4)}
                </Text>
            </View>
        </TouchableOpacity>
    )
}


